text:
.form-selection {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background-color: var(--color-surface-base);
  padding: 6px;
  border: 1px solid var(--color-primary-default);
  border-radius: 10px;

  &.credentials-confirmation {
    width: fit-content;
    min-width: 380px;
    margin-inline: auto;
  }

  & .selection-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-rows: auto;
    gap: 12px;
    padding-inline: 12px;

    & .config-column {
      display: flex;
      flex-direction: column;
      gap: 8px;

      .credentials-confirmation & {
        gap: 12px;
        padding-block: 15px;
      }
    }

    .credentials-confirmation & {
      padding-inline: 15px;
    }

    .single & {
      display: block;
    }
  }

  & .config-item-icon {
    height: 18px;
    width: 18px;
    -moz-context-properties: fill, stroke, stroke-opacity;
    fill: light-dark(color-mix(in srgb, #bdbdbd 20%, transparent), color-mix(in srgb, #3d4d67 20%, transparent));
    stroke: light-dark(#bdbdbd, #3d4d67);

    &.lighter {
      fill: light-dark(color-mix(in srgb, #bdbdbd 5%, transparent), color-mix(in srgb, #3d4d67 5%, transparent));
    }

    .config-protocols & {
      height: 30px;
      width: 30px;
    }
  }

  & .config-protocols {
    background-color: var(--color-primary-soft);
    padding-block: 10px;
    border-radius: 6px;

    & .protocol-title {
      color: light-dark(#2176d6, #feffff);
      font-weight: 500;
      font-size: 1.3rem;
      display: inline-block;
      text-transform: uppercase;
    }

    & .protocol-data {
      font-size: 1rem;
      color: var(--color-text-secondary);
    }
  }

  & .config-detail {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 9px;

    .config-protocols & {
      padding-block: 0;
    }

    & .config-item-data {
      overflow: hidden;
      display: flex;
      flex-direction: column;
      gap: 2px;

      & p {
        overflow: hidden;
        text-overflow: ellipsis;
        line-height: normal;
        margin: 0;

        &.title {
          text-transform: uppercase;
          color: var(--color-text-secondary);
          font-weight: 500;
          font-size: 0.8rem;
          display: inline-block;
          vertical-align: bottom;
        }

        &.data {
          color: var(--color-text-base);
          font-weight: 400;
          font-size: 1rem;
        }
      }

      & .info-badge {
        font-size: 0.8rem;
        line-height: 1;
      }
